// --- LOGIN (Kima kan 3ndek + logic error west l-box) ---
const Login = () => {
  const [formData, setFormData] = useState({ username: '', password: '' });
  const [error, setError] = useState(""); //

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/login/', formData);
      localStorage.setItem('username', res.data.username || formData.username.split('@')[0]);
      window.location.href = "/";
    } catch (err) {
      setError("❌ Identifiants incorrects.");
    }
  };

  return (
    <div className="relative min-h-screen flex items-center justify-center">
        <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591" className="absolute inset-0 w-full h-full object-cover" alt="bg" />
        <div className="absolute inset-0 bg-black/60 backdrop-blur-[4px]"></div>
        <div className="relative z-10 max-w-md w-full bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
          {error && <p className="mb-6 text-center text-red-400 font-bold text-sm italic">{error}</p>}
          <form className="space-y-6" onSubmit={handleLogin}>
            <input type="text" placeholder="VOTRE EMAIL" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 font-bold" onChange={(e) => setFormData({...formData, username: e.target.value})} />
            <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 font-bold" onChange={(e) => setFormData({...formData, password: e.target.value})} />
            <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase">Se Connecter</button>
          </form>
        </div>
    </div>
  );
};

